// Feedback report 14 (2026-10-16, info@wellingtonroof.co.nz) — "Hip & Valley
// Detail Disappears: this detail disappears after saving, not sure why, have
// had to redraw 2 times?"
//
// His dutch gable has a bump-out in the bottom eave, and he had hand-drawn
// the little hip-and-valley structure over it — a short ridge, two valleys up
// into the main roof, two hips down to the corners — because no builder draws
// that. Five lines, no autoGenerated mark, which is what makes them HIS.
//
// The save was never the culprit: snapshotCurrentJob -> restoreFromJob keeps
// them to the point (pinned below). autoGenerateRoof did it. It opens with
// clearRoofLines(), which was `DRAW.lines = []` — so every rebuild took the
// office's lines with the builder's: Rotate roof 90°, re-picking the shape,
// and worst of all the dutch gablet slider, which regenerates on `oninput`
// and so wiped them on the first pixel of a drag, from a panel that slides
// itself open over the canvas a second after the roof lands.
//
// regenerateAutoRoofLines — the corner-drag path — has never done this ("a
// line drawn anywhere else is the office's and stays", report 64). The two
// paths disagreed; they do not now. The filter is the regen's, plus a dedupe
// against what the builder is about to draw, so a rebuild cannot double up.
//
// THE CASES WITH NOTHING HAND-DRAWN ARE BYTE-IDENTICAL to the old behaviour —
// measured against the pre-fix build, sheet counts included — which is what
// makes this safe on a path this repo records as broken twice.
import { fileURLToPath as _f } from 'node:url';
import { dirname as _d, join as _j } from 'node:path';
import { chromium } from 'playwright';
const DIR = _j(_d(_f(import.meta.url)), '..', 'frontend');
const results = [];
function check(n, ok, d){ results.push(!!ok); console.log((ok?'PASS':'FAIL')+'  '+n+(d?('  — '+d):'')); }

// His outline and his five lines, exactly as the report printed them.
const OUT = [[998,417],[1575,417],[1575,740],[1297,740],[1297,767],[1136,767],[1136,740],[998,740]];
const DETAIL = [
  ['ridge',  [[1217,669],[1217,699]]],
  ['valley', [[1217,669],[1136,740]]],
  ['valley', [[1217,669],[1297,740]]],
  ['hip',    [[1217,699],[1136,767]]],
  ['hip',    [[1217,699],[1297,767]]],
];
const RECT = [[800,400],[1600,400],[1600,800],[800,800]];
const SCALE = 0.059468750000001055;

const b = await chromium.launch();
const ctx = await b.newContext({ viewport:{ width:1500, height:1000 } });
const pg = await ctx.newPage();
const errs = []; pg.on('pageerror', e => errs.push(e.message)); pg.on('dialog', d => d.accept());
await pg.route('**/api.mapbox.com/**', r => r.abort());
await pg.route('**/flood-roofing-estimator-production.up.railway.app/**', r => {
  const u = r.request().url();
  if (/\/settings/.test(u)) return r.fulfill({ status:200, contentType:'application/json',
    body: JSON.stringify({ user_id:'u1', branding:{ company_name:'WLRR' }, quote_defaults:{}, jms_keys:{} }) });
  return r.fulfill({ status:200, contentType:'application/json', body:'[]' });
});
await pg.addInitScript(() => { localStorage.setItem('fr_token','t'); localStorage.setItem('fr_setup_done','1');
  localStorage.setItem('fr_site_mode','off');
  localStorage.setItem('fr_user', JSON.stringify({ email:'info@wellingtonroof.co.nz', name:'S' }));
  localStorage.setItem('fr_company', JSON.stringify({ id:'c1', name:'WLRR' })); });
await pg.goto('file://' + DIR + '/app.html');
await pg.waitForTimeout(2800);
await pg.evaluate(() => { const w = document.getElementById('setupWizard'); if (w) w.remove(); gotoTab('roof'); });

// His roof, with the detail drawn the way a roofer draws it: pick the tool,
// two points, finish. Returns how many of his five lines the roof holds.
const drawHis = async (then) => pg.evaluate(async ([OUT, DETAIL, SCALE, then]) => {
  const isHand = l => l && !l.autoGenerated && /^(ridge|hip|valley)$/.test(l.type);
  clearAll(true);
  DRAW.scaleMetresPerPx = SCALE;
  setTool('outline'); DRAW.currentPts = OUT.map(p => p.slice()); finishCurrent();
  const m = document.getElementById('_rsModal'); if (m) m.remove();
  autoGenerateRoof('dutch', 0);
  DETAIL.forEach(([t, pts]) => { setTool(t); DRAW.currentPts = pts.map(p => p.slice()); finishCurrent(); });
  autoCalcLineMeasurements(); _syncCurrentToRoof(); redrawAll();
  const before = (DRAW.lines || []).filter(isHand).length;
  let threw = '';
  if (then) { try { await eval(then); } catch(e){ threw = e.message; } }
  await new Promise(r => setTimeout(r, 200));
  const roof0 = (DRAW.roofs && DRAW.roofs[0]) ? (DRAW.roofs[0].lines || []).filter(isHand).length : -1;
  return { before, live: (DRAW.lines || []).filter(isHand).length, roof0, threw };
}, [OUT, DETAIL, SCALE, then || '']);

const base = await drawHis(null);
check('his five hand-drawn lines land on the roof', base.before === 5 && base.roof0 === 5, JSON.stringify(base));

for (const [name, code] of [
  ['Rotate roof 90°',                 `rotateActiveRoof()`],
  ['the dutch gablet slider',         `setDutchGabletFrac(0.6, true)`],
  ['re-picking the same shape',       `_pickRoofType('dutch')`],
  ['picking a different shape',       `_pickRoofType('hip')`],
  ['a corner drag (the regen path)',  `(function(){ DRAW.outline[1]=[1580,412]; regenerateAutoRoofLines('dutch'); _syncCurrentToRoof(); })()`],
]) {
  const r = await drawHis(code);
  check('the detail survives ' + name, r.roof0 === 5 && r.live === 5 && !r.threw, JSON.stringify(r));
}

// The save was never the culprit — pin the round trip so it stays that way.
const trip = await pg.evaluate(() => {
  const isHand = l => l && !l.autoGenerated && /^(ridge|hip|valley)$/.test(l.type);
  const snap = snapshotCurrentJob();
  const inSnap = ((snap.draw.roofs || [])[0] || {}).lines || [];
  restoreFromJob(JSON.parse(JSON.stringify(snap)));
  return { saved: inSnap.filter(isHand).length,
           reopened: ((DRAW.roofs || [])[0] || {}).lines.filter(isHand).length,
           live: (DRAW.lines || []).filter(isHand).length };
});
check('a save writes the detail and a reopen reads it back', trip.saved === 5 && trip.reopened === 5 && trip.live === 5, JSON.stringify(trip));

// ── and the three things the fix must NOT do ─────────────────────
const safe = await pg.evaluate(([OUT, RECT, SCALE]) => {
  const out = {};
  const sig = () => (DRAW.lines || []).map(l => l.type + ':' + l.pts.map(p => p.map(Math.round).join(',')).join('-')).sort().join('|');
  const lay = (ol) => { clearAll(true); DRAW.scaleMetresPerPx = SCALE; setTool('outline');
    DRAW.currentPts = ol.map(p => p.slice()); finishCurrent();
    const m = document.getElementById('_rsModal'); if (m) m.remove(); };

  // 1. A rebuild is idempotent — nothing doubles up.
  lay(OUT); autoGenerateRoof('dutch', 0);
  const once = sig(), n1 = DRAW.lines.length;
  autoGenerateRoof('dutch', 0);
  out.idempotent = (sig() === once && DRAW.lines.length === n1);
  out.idempotentD = n1 + ' -> ' + DRAW.lines.length;

  // 2. Changing type leaves no stale structure behind (report 64's lesson).
  lay(RECT); autoGenerateRoof('hip', 0); autoGenerateRoof('gable', 0);
  const switched = DRAW.lines.length;
  lay(RECT); autoGenerateRoof('gable', 0);
  out.noStale = (switched === DRAW.lines.length);
  out.noStaleD = 'hip->gable ' + switched + ' vs fresh gable ' + DRAW.lines.length;

  // 3. An UNMARKED copy of the builder's own structure is still dropped — the
  //    roof that carried two structures at once (report 64).
  lay(RECT); autoGenerateRoof('gable', 0);
  DRAW.lines.forEach(l => { delete l.autoGenerated; });
  autoGenerateRoof('gable', 0);
  out.unmarkedDropped = (DRAW.lines.length === switched);
  out.unmarkedD = DRAW.lines.length + ' vs ' + switched;

  // 4. A hand line laid exactly over the builder's own does not double it.
  lay(RECT); autoGenerateRoof('gable', 0);
  const rg = DRAW.lines.filter(l => l.type === 'ridge')[0];
  setTool('ridge'); DRAW.currentPts = [rg.pts[0].slice(), rg.pts[1].slice()]; finishCurrent();
  out.copies = DRAW.lines.filter(l => l.type === 'ridge').length;
  autoGenerateRoof('gable', 0);
  out.afterRebuild = DRAW.lines.filter(l => l.type === 'ridge').length;

  // 5. The sheet count does not move. The gablet fraction is pinned here on
  //    purpose: it is a per-roof field that outlives clearAll, so a case
  //    above that moved the slider would otherwise decide this count.
  lay(OUT); DRAW.calPitch = 25; DRAW.dutchGabletFrac = 0.5; autoGenerateRoof('dutch', 0);
  autoCalcLineMeasurements(); renderRoofSheetPlan();
  const g = ((window._lastSheetCounts || {}).engineGroups || (window._lastSheetCounts || {}).groups) || {};
  out.sheets = Object.keys(g).map(k => g[k].orderedMm + 'x' + g[k].count).sort().join(' ');
  return out;
}, [OUT, RECT, SCALE]);

check('a rebuild is idempotent — nothing doubles up', safe.idempotent, safe.idempotentD);
check('changing the type leaves no stale structure', safe.noStale, safe.noStaleD);
check('an UNMARKED copy of the builder\'s structure is still dropped (report 64)', safe.unmarkedDropped, safe.unmarkedD);
check('a hand line over the builder\'s own collapses back to one', safe.copies === 2 && safe.afterRebuild === 1, safe.copies + ' -> ' + safe.afterRebuild);
// Measured on the pre-fix build: the counts must not have moved at all.
check('the sheet count is exactly what it was before the fix',
  safe.sheets === '10597x54 12369x13 5299x52', safe.sheets);

check('nothing threw', errs.length === 0, errs.join(' | ') || 'clean');
await b.close();
const bad = results.filter(x => !x).length;
console.log('\n' + (results.length - bad) + '/' + results.length + ' passed');
process.exit(bad ? 1 : 0);
